import copy,json,sys
from pathlib import Path
from uuid import UUID
sys.path[:0]=[str(Path('mashos-api-current/ai/services/ai_inference').resolve())]
from analysis_semantic_map import prepare_semantic_map,build_semantic_map,_canonical,_hash,MODEL_SCHEMA
from cocolon_meaning_experience_engine.cores.analysis.semantic_admission import AnalysisModelQuotedParentUnitsResponse
import hashlib
OWNER=str(UUID(int=1))
seed=json.loads(Path('mashos-api-current/ai/tests/fixtures/analysis-semantic-map-10-request-20261107.json').read_text())
base=seed['source_snapshot']

def snapshot(records):
 s=copy.deepcopy(base);s['members']=[]
 for i,(memo,action,category,emotion,strength) in enumerate(records):
  m=copy.deepcopy(base['members'][0]);m['original'].update(id=str(UUID(int=101+i)),memo=memo,memo_action=action,category=[category],emotions=[emotion],emotion_details=[{'type':emotion,'strength':strength}]);s['members'].append(m)
 return s

def node(kind,title,summary,explanation,fields,unknowns=None,perspective='SELF'):
 return dict(node_kind=kind,title=title,summary=summary,explanation=explanation,perspective=perspective,unknowns=unknowns or [],_fields=fields)
def edge(a,b,kind,label,explanation):return dict(from_=a,to=b,relation_kind=kind,label=label,explanation=explanation)

def row(id,snap,title,summary,nodes,edges):
 p=prepare_semantic_map(OWNER,snap);fields={r['field']:r['text'] for r in json.loads(p.material_json)['fields']}
 target=dict(schema_version=MODEL_SCHEMA,overview=dict(title=title,summary=summary),nodes=[],edges=[])
 for i,n in enumerate(nodes,1):
  n=copy.deepcopy(n);indices=n.pop('_fields');n['node_id']='n'+str(i);n['evidence']=[dict(field=k,quote=fields[k]) for k in indices];target['nodes'].append(n)
 for e in edges:
  e=copy.deepcopy(e);e['from']='n'+str(e.pop('from_'));e['to']='n'+str(e['to']);target['edges'].append(e)
 raw=_canonical(target)
 response=AnalysisModelQuotedParentUnitsResponse(p.request_ref,_hash(p.messages()),hashlib.sha256(raw.encode()).hexdigest(),'stop',raw)
 artifact,coverage=build_semantic_map(p,response)
 return dict(id=id,owner=OWNER,snapshot=snap,request_ref=p.request_ref,messages=p.messages(),assistant_target=raw,expected_coverage=coverage)

